const go=path=>{window.location.hash=path;};
const countLessons=n=>n+' '+plural(n,'урок','урока','уроков');
const icons=[LayoutDashboard,BookOpen,Dumbbell,ChartNoAxesCombined,Brain,Library,Languages,FolderOpen,NotebookPen];
const nav=[['/','Обзор'],['/course','Мой маршрут'],['/practice','Практикум'],['/simulator','Тренажёр рынка'],['/psychology','Психология'],['/library','Библиотека'],['/glossary','Словарь терминов'],['/knowledge','База знаний'],['/journal','Журнал и сделки']];
const mobileNav=[['/','Обзор',LayoutDashboard],['/course','Маршрут',BookOpen],['/journal','Журнал',NotebookPen],['/simulator','Тренажёр',ChartNoAxesCombined]];
const pages=['overview','course','lesson','practice','simulator','psychology','library','glossary','knowledge','journal'];
const isMac=typeof navigator!=='undefined'&&/Mac|iPhone|iPad/.test(navigator.platform||navigator.userAgent);
const formatDate=()=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',weekday:'short'}).format(new Date());
const lessonMinutes=l=>Math.max(5,Math.round((l.explain.reduce((n,[t,b])=>n+t.length+b.length,0)+l.example.length+l.task.length)/900)+4);

export default function App(){
 const [route,setRoute]=useState(location.hash.slice(1)||'/');
 const [completed,setCompleted]=useStored('campus.completed',[]),[notes,setNotes]=useStored('campus.notes',{}),[journal,setJournal]=useStored('campus.journal',[]),[last,setLast]=useStored('campus.last',lessons[0].id);
 const [stats,setStatsRaw]=useStored('campus.stats',emptyStats),[cards,setCards]=useStored('campus.cards',{}),[plan,setPlan]=useStored('campus.plan',emptyPlan),[activity,setActivity]=useStored('campus.activity',{}),[theme,setTheme]=useStored('campus.theme','system');
 const [catalog,setCatalog]=useState([]),[knowledge,setKnowledge]=useState([]),[sourceMap,setSourceMap]=useState({}),[report,setReport]=useState(null);
 const [searchOpen,setSearchOpen]=useState(false),[search,setSearch]=useState(''),[mobile,setMobile]=useState(false),[notice,setNotice]=useState(''),[installOpen,setInstallOpen]=useState(false);
 const main=useRef();
 const fullStats={...emptyStats,...stats};
 const setStats=fn=>setStatsRaw(s=>fn({...emptyStats,...s}));
 const track=(kind='practice')=>{const day=todayKey();setActivity(a=>({...a,[day]:{...(a[day]||{}),[kind]:((a[day]||{})[kind]||0)+1}}));};
 useEffect(()=>{const fn=()=>{setRoute(location.hash.slice(1)||'/');setMobile(false);};window.addEventListener('hashchange',fn);return()=>window.removeEventListener('hashchange',fn);},[]);
 useEffect(()=>{main.current?.scrollTo({top:0,behavior:'instant'});},[route.split('?')[0]]);
 useEffect(()=>{const root=document.documentElement;if(theme==='system')delete root.dataset.theme;else root.dataset.theme=theme;},[theme]);
 useEffect(()=>{Promise.all([fetch(publicAsset('/data/catalog.json')).then(r=>r.json()),fetch(publicAsset('/data/knowledge.json')).then(r=>r.json()),fetch(publicAsset('/data/source-map.json')).then(r=>r.json()),fetch(publicAsset('/data/quality-report.json')).then(r=>r.json())]).then(([c,k,s,r])=>{setCatalog(c);setKnowledge(k);setSourceMap(s);setReport(r);}).catch(()=>setNotice('Не удалось загрузить библиотеку. Проверь соединение и обнови страницу.'));},[]);
 useEffect(()=>{const fn=e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setSearchOpen(true);}if(e.key==='Escape'){setSearchOpen(false);setMobile(false);}};window.addEventListener('keydown',fn);return()=>window.removeEventListener('keydown',fn);},[]);
 useEffect(()=>{if(!notice)return;const t=setTimeout(()=>setNotice(''),4200);return()=>clearTimeout(t);},[notice]);
 const [path,query='']=route.split('?');const parts=path.split('/').filter(Boolean);const page=parts[0]||'overview';
 const active=page==='lesson'?'course':page;
 const openLesson=id=>{setLast(id);go('/lesson/'+id);};
 const saveEntry=entry=>{setJournal(j=>[{...entry,id:uid(),date:new Date().toISOString()},...j]);track('journal');setNotice('Запись сохранена в журнале');};
 const pct=Math.round(completed.length/lessons.length*100);
 const next=lessons.find(l=>l.id===last&&!completed.includes(l.id))||lessons.find(l=>!completed.includes(l.id))||lessons[0];
 const xp=computeXp({completed,journal,stats:fullStats,cards});const level=levelFor(xp);const streak=streakDays(Object.keys(activity),todayKey());
 const cycleTheme=()=>setTheme(t=>t==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'light':'dark'):t==='dark'?'light':'dark');
 const q=search.trim().toLowerCase();
 const searchResults=q?[
  ...lessons.filter(l=>(l.title+' '+l.subtitle+' '+l.moduleTitle).toLowerCase().includes(q)).map(l=>({title:l.title,sub:'Урок · '+l.moduleTitle,action:()=>openLesson(l.id)})),
  ...drills.filter(d=>(d.title+' '+d.text).toLowerCase().includes(q)).map(d=>({title:d.title,sub:'Практикум',action:()=>go('/practice/'+d.id)})),
  ...glossary.filter(g=>(g.term+' '+g.ru).toLowerCase().includes(q)).map(g=>({title:g.ru,sub:'Термин · '+g.term,action:()=>go('/glossary?q='+encodeURIComponent(g.term))})),
  ...catalog.filter(b=>(b.title+' '+b.author).toLowerCase().includes(q)).map(b=>({title:b.title,sub:'Книга · '+b.author,action:()=>go('/library/'+b.id)}))
 ].slice(0,16):[];
 const pageTitle=page==='lesson'?'Урок':nav.find(([u])=>u.slice(1)===page)?.[1]||'Обзор';
 return <div className="app-shell">
  <button className={'mobile-backdrop '+(mobile?'shown':'')} onClick={()=>setMobile(false)} aria-label="Закрыть боковое меню" tabIndex={mobile?0:-1}/>
  <aside id="main-menu" className={'sidebar '+(mobile?'open':'')} aria-label="Главное меню">
   <div className="sidebar-top"><button className="brand" onClick={()=>go('/')} aria-label="На главную"><span className="brand-symbol"><i/><i/><i/></span><span>место<span>обучения</span></span></button><button className="icon-button sidebar-close" aria-label="Закрыть меню" onClick={()=>setMobile(false)}><X size={20}/></button></div>
   <nav>{nav.map(([url,title],i)=>{const Icon=icons[i];const selected=url==='/'?page==='overview':active===url.slice(1);return <button className={'nav-item '+(selected?'active':'')} aria-current={selected?'page':undefined} onClick={()=>go(url)} key={url}><Icon size={19}/><span>{title}</span>{url==='/course'&&<small>{completed.length}/{lessons.length}</small>}{url==='/practice'&&<small className="new">new</small>}</button>;})}</nav>
   <button className="sidebar-install" onClick={()=>{setMobile(false);setInstallOpen(true);}}><Smartphone size={19}/><span>На экран «Домой»</span></button>
   <div className="sidebar-bottom"><div className="level-card"><div className="level-top"><span className="level-badge"><Trophy size={15}/></span><div><b>{level.name}</b><small>{xp} XP · уровень {level.index+1}</small></div>{streak>0&&<span className="streak-chip" title="Дней подряд"><Flame size={14}/>{streak}</span>}</div><div className="progress-track"><i style={{width:level.progress*100+'%'}}/></div><small>{level.progress<1?`${level.to-xp} XP до следующего уровня`:'Максимальный уровень'}</small></div><div className="side-progress"><span>Твой маршрут <b>{pct}%</b></span><div className="progress-track"><i style={{width:pct+'%'}}/></div><small>{completed.length} из {lessons.length} уроков завершено</small></div><div className="profile"><div className="avatar">Р</div><div><b>Руслан</b><span>Учусь в своём темпе</span></div><button className="icon-button theme-toggle" onClick={cycleTheme} aria-label="Переключить тему">{(theme==='dark'||(theme==='system'&&typeof matchMedia!=='undefined'&&matchMedia('(prefers-color-scheme: dark)').matches))?<Sun size={18}/>:<Moon size={18}/>}</button></div></div>
  </aside>
  <div className="workspace"><header className="topbar"><div className="top-left"><button className="icon-button menu-button" aria-label="Открыть меню" aria-expanded={mobile} aria-controls="main-menu" onClick={()=>setMobile(!mobile)}><Menu size={22}/></button><span className="breadcrumb"><span className="crumb-root">Моё пространство</span> <ChevronRight size={13}/> <b>{pageTitle}</b></span></div><button className="search-trigger" aria-label="Поиск по платформе" onClick={()=>setSearchOpen(true)}><Search size={17}/><span>Найти урок, термин, книгу</span><kbd>{isMac?'⌘':'Ctrl'} K</kbd></button><div className="header-date">{streak>0&&<span className="streak-chip"><Flame size={14}/>{streak} {plural(streak,'день','дня','дней')}</span>}<span className="date-text">{formatDate()}</span><button className="icon-button theme-toggle" onClick={cycleTheme} aria-label="Переключить тему">{(theme==='dark'||(theme==='system'&&typeof matchMedia!=='undefined'&&matchMedia('(prefers-color-scheme: dark)').matches))?<Sun size={18}/>:<Moon size={18}/>}</button></div></header>
  <main ref={main}><ProgressNotice/><AppExperience open={installOpen} onClose={()=>setInstallOpen(false)} onOpen={()=>setInstallOpen(true)} showCard={page==='overview'}/>
   <div className="route" key={page+(parts[1]||'')}>
   {page==='overview'&&<Dashboard {...{completed,pct,next,catalog,openLesson,xp,level,streak,activity,cards,stats:fullStats,plan}}/>}
   {page==='course'&&<Course {...{completed,openLesson}} moduleId={parts[1]}/>}
   {page==='lesson'&&(lessons.some(l=>l.id===parts[1])?<Lesson key={parts[1]} lesson={lessons.find(l=>l.id===parts[1])} {...{completed,openLesson,catalog,sourceMap}} note={notes[parts[1]]||''} setNote={value=>setNotes(n=>({...n,[parts[1]]:value}))} complete={id=>{if(!completed.includes(id)){setCompleted(c=>c.includes(id)?c:[...c,id]);track('lesson');}setNotice('Урок завершён. +60 XP');}}/>:<NotFound text="Такого урока нет. Возможно, ссылка устарела."/>)}
   {page==='practice'&&<Practice tab={parts[1]} {...{stats:fullStats,setStats,cards,setCards,plan,setPlan,saveEntry,openLesson}} track={()=>track('practice')}/>}
   {page==='simulator'&&<Simulator saveEntry={saveEntry} track={()=>{setStats(s=>({...s,sim:{trades:(s.sim.trades||0)+1}}));track('practice');}}/>}
   {page==='psychology'&&<Psychology openLesson={openLesson} saveEntry={saveEntry}/>}
   {page==='library'&&<LibraryView {...{catalog,report,sourceMap}} bookId={parts[1]} query={query}/>}
   {page==='glossary'&&<Glossary query={new URLSearchParams(query).get('q')||''}/>}
   {page==='knowledge'&&<Knowledge items={knowledge} selected={parts[1]}/>}
   {page==='journal'&&<TradingJournal entries={journal} saveEntry={saveEntry} setEntries={setJournal} notify={setNotice}/>}
   {!pages.includes(page)&&<NotFound text="Такой страницы нет."/>}
   </div>
  </main>
  <nav className="bottom-nav" aria-label="Быстрая навигация">{mobileNav.map(([url,title,Icon])=>{const selected=url==='/'?page==='overview':active===url.slice(1);return <button key={url} className={selected?'active':''} aria-current={selected?'page':undefined} onClick={()=>go(url)}><Icon size={21}/><span>{title}</span></button>;})}<button className={(mobile||!['overview','course','journal','simulator'].includes(active))?'active':''} aria-label="Ещё разделы" aria-expanded={mobile} aria-controls="main-menu" onClick={()=>setMobile(true)}><Ellipsis size={21}/><span>Ещё</span></button></nav>
  </div>
  {notice&&<div role="status" className="toast"><CheckCircle2 size={19}/>{notice}</div>}
  {searchOpen&&<div className="modal-backdrop" onClick={()=>setSearchOpen(false)}><section role="dialog" aria-modal="true" aria-label="Поиск по платформе" className="search-modal" onClick={e=>e.stopPropagation()}><div className="search-modal-input"><Search size={21}/><input autoFocus placeholder="Урок, упражнение, автор, термин…" value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&searchResults[0]){searchResults[0].action();setSearchOpen(false);}}}/><button className="icon-button" aria-label="Закрыть поиск" onClick={()=>setSearchOpen(false)}><X size={20}/></button></div><div className="search-results">{!search?<div className="search-hints"><p>Например:</p>{['риск','стоп','тильт','Мёрфи','spread','карточки'].map(t=><button key={t} onClick={()=>setSearch(t)}>{t}</button>)}</div>:searchResults.length?searchResults.map((r,i)=><button key={i} style={{'--i':i}} onClick={()=>{r.action();setSearchOpen(false);}}><div><b>{r.title}</b><small>{r.sub}</small></div><ArrowUpRight size={17}/></button>):<p>Совпадений нет. Попробуй более короткое слово.</p>}</div></section></div>}
 </div>;
}

function NotFound({text}){return <div className="page"><div className="empty-state panel"><Compass size={34}/><h3>{text}</h3><button className="primary" onClick={()=>go('/')}>Вернуться к обучению</button></div></div>;}

function WeekStrip({activity}){
 const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return {key,label:new Intl.DateTimeFormat('ru-RU',{weekday:'short'}).format(d).slice(0,2),active:!!activity[key],today:i===6};});
 return <div className="week-strip">{days.map(d=><span key={d.key} className={(d.active?'on ':'')+(d.today?'today':'')}><i>{d.active?<Check size={13}/>:null}</i><small>{d.label}</small></span>)}</div>;
}

function Dashboard({completed,pct,next,catalog,openLesson,xp,level,streak,activity,cards,stats,plan}){
 const heroCandles=useMemo(()=>makeCandles(34),[]);
 const today=activity[todayKey()]||{};
 const goals=[['Пройти урок',today.lesson,()=>openLesson(next.id)],['Сделать упражнение',today.practice,()=>go('/practice')],['Записать вывод в журнал',today.journal,()=>go('/journal')]];
 const doneGoals=goals.filter(g=>g[1]).length;
 return <div className="page dashboard"><div className="page-heading"><div><div className="eyebrow">ТВОЙ ПУТЬ В ТРЕЙДИНГЕ</div><h1>Разобраться. Попробовать. Понять.</h1><p>Рынок по полочкам — через схемы, примеры и собственные решения.</p></div><span className="quiet-tag"><span className="tiny-dot"/> В своём темпе</span></div>
 <section className="hero"><div className="hero-glow"/><div className="hero-copy"><span className="hero-kicker">МЕСТО ОБУЧЕНИЯ <i/> РЫНОК + РИСК + ПСИХОЛОГИЯ</span><h2>Меньше догадок.<br/>Больше понимания.</h2><p>Разбирай одну идею за раз.<br/>Смотри, как она работает. Проверяй руками.</p><div className="hero-actions"><button className="hero-button" onClick={()=>openLesson(next.id)}>{completed.length?'Продолжить обучение':'Начать свой маршрут'}<ArrowRight size={18}/></button><button className="hero-ghost" onClick={()=>go('/practice')}><Dumbbell size={17}/> Практикум</button></div><span className="hero-caption">{lessons.length} уроков · 6 тренажёров · симулятор рынка · на русском</span></div><div className="hero-visual"><div className="hero-chart-head"><span><i/> УЧИМСЯ ВИДЕТЬ СТРУКТУРУ</span><span>M15 / ДЕМО</span></div><Chart candles={heroCandles} visible={40} compact stagger/><div className="chart-annotation"><span className="annotation-icon"><Target size={17}/></span><div><b>Сначала план. Потом решение.</b><small>Цена — наблюдение, прогноз — гипотеза.</small></div></div></div></section>
 <div className="dashboard-stats stagger"><div style={{'--i':0}}><span className="stat-icon violet"><Trophy size={20}/></span><span><b>{level.name}</b><small>{xp} XP · ур. {level.index+1}</small></span></div><div style={{'--i':1}}><span className="stat-icon peach"><Flame size={20}/></span><span><b>{streak} {plural(streak,'день','дня','дней')} подряд</b><small>{streak?'не прерывай серию':'начни серию сегодня'}</small></span></div><div style={{'--i':2}}><span className="stat-icon sage"><BookOpen size={20}/></span><span><b>{completed.length} / {lessons.length} уроков</b><small>маршрут пройден на {pct}%</small></span></div><div style={{'--i':3}}><span className="stat-icon rose"><Library size={20}/></span><span><b>{catalog.length||13} источников</b><small>с русскими разборами</small></span></div></div>
 <div className="dashboard-grid"><section><div className="today-card"><div className="section-title"><h2>План на сегодня</h2><small>{doneGoals}/3 выполнено</small></div><div className="today-goals">{goals.map(([t,done,action],i)=><button key={t} className={done?'done':''} onClick={action}><span className="goal-check">{done?<Check size={15}/>:i+1}</span><span>{t}</span><ArrowUpRight size={16}/></button>)}</div><WeekStrip activity={activity}/></div>
 <div className="section-title"><h2>Твой учебный маршрут</h2><button className="text-button" onClick={()=>go('/course')}>Все уроки <ArrowRight size={15}/></button></div><div className="module-grid stagger">{modules.map((m,i)=>{const count=m.lessons.filter(l=>completed.includes(l.id)).length;return <button className="module-card" key={m.id} style={{'--i':i,'--mc':m.color}} onClick={()=>go('/course/'+m.id)}><div className="module-card-top"><span className="module-number">{m.number}</span>{count===m.lessons.length?<span className="module-done"><Check size={14}/> пройден</span>:<ArrowUpRight size={17}/>}</div><h3>{m.title}</h3><p>{m.description}</p><div className="module-card-bottom"><small>{countLessons(m.lessons.length)}</small><div className="tiny-track"><i style={{width:count/m.lessons.length*100+'%'}}/></div><small>{count}/{m.lessons.length}</small></div></button>;})}</div>
 <div className="section-title"><h2>Практикум</h2><button className="text-button" onClick={()=>go('/practice')}>Все упражнения <ArrowRight size={15}/></button></div><div className="drill-strip stagger">{drills.map((d,i)=>{const Icon=d.icon;return <button key={d.id} style={{'--i':i,'--accent-c':d.color}} onClick={()=>go('/practice/'+d.id)}><span className="drill-icon"><Icon size={20}/></span><b>{d.title}</b></button>;})}</div></section>
 <aside className="dashboard-right"><section className="continue-card"><span className="eyebrow">СЛЕДУЮЩИЙ ШАГ</span><div className="continue-icon"><BookOpen size={24}/></div><h3>{next.title}</h3><p>{next.subtitle}</p><button className="primary full" onClick={()=>openLesson(next.id)}>Открыть урок <ArrowRight size={16}/></button></section><section className="practice-card"><span className="eyebrow">ОТ ЗНАНИЯ К ДЕЙСТВИЮ</span><h3>Попробуй без риска<br/>для реальных денег</h3><div className="mini-candles">{[25,40,32,55,43,68,59,81,64,90].map((h,i)=><i key={i} className={i%3?'up':'down'} style={{height:h/1.4,'--i':i}}/>)}</div><button className="text-button" onClick={()=>go('/simulator')}>В тренажёр рынка <ArrowUpRight size={17}/></button></section><section className="practice-card plan-mini"><span className="eyebrow">ТОРГОВЫЙ ПЛАН</span><h3>{planCompleteness(plan)===100?'План готов':'Заполнено '+planCompleteness(plan)+'%'}</h3><div className="progress-track"><i style={{width:planCompleteness(plan)+'%'}}/></div><button className="text-button" onClick={()=>go('/practice/plan')}>{planCompleteness(plan)?'Открыть план':'Составить план'} <ArrowUpRight size={17}/></button></section><div className="soft-note"><Lightbulb size={19}/><p>Не нужно понимать всё сразу. Один проверенный навык важнее десяти новых терминов.</p></div></aside></div>
 </div>;
}

function Course({completed,openLesson,moduleId}){
 const selected=modules.find(m=>m.id===moduleId)||modules[0];
 return <div className="page"><PageHead label="ПОСЛЕДОВАТЕЛЬНОЕ ОБУЧЕНИЕ" title="Твой маршрут" text="Каждый урок: объяснение → наглядный пример → действие → проверка понимания."/><div className="course-layout"><aside className="module-menu">{modules.map(m=><button key={m.id} style={{'--mc':m.color}} className={m.id===selected.id?'selected':''} onClick={()=>go('/course/'+m.id)}><span>{m.number}</span><div><b>{m.title}</b><small>{m.lessons.filter(l=>completed.includes(l.id)).length} / {m.lessons.length} завершено</small></div><ChevronRight size={16}/></button>)}</aside><section className="lesson-list stagger" key={selected.id}><div className="module-intro"><span className="eyebrow">МОДУЛЬ {selected.number}</span><h2>{selected.title}</h2><p>{selected.description}</p></div>{selected.lessons.map((l,i)=><button key={l.id} style={{'--i':i}} onClick={()=>openLesson(l.id)} className="lesson-row"><span className={'lesson-index '+(completed.includes(l.id)?'done':'')}>{completed.includes(l.id)?<Check size={20}/>:String(i+1).padStart(2,'0')}</span><div><h3>{l.title}</h3><p>{l.subtitle}</p></div><span className="lesson-time"><Clock size={13}/> ~{lessonMinutes(l)} мин</span><ArrowUpRight size={19}/></button>)}</section></div></div>;
}

function Lesson({lesson:l,completed,complete,openLesson,note,setNote,catalog,sourceMap}){
 const [tab,setTab]=useState(0);
 const position=lessons.findIndex(x=>x.id===l.id),next=lessons[position+1];
 return <div className="page lesson-page"><button className="back-link" onClick={()=>go('/course/'+l.moduleId)}><ArrowLeft size={16}/> {l.moduleTitle}</button><div className="lesson-heading"><div className="eyebrow">УРОК {position+1} ИЗ {lessons.length} · {l.moduleTitle.toUpperCase()}</div><div className="lesson-progress-line"><i style={{width:(position+1)/lessons.length*100+'%'}}/></div><h1>{l.title}</h1><p>{l.subtitle}</p></div><div className="lesson-tabs" role="tablist">{['Разобраться','Попробовать руками','Проверить себя'].map((t,i)=><button key={t} role="tab" aria-selected={tab===i} className={tab===i?'active':''} onClick={()=>setTab(i)}><span>0{i+1}</span>{t}{i===2&&completed.includes(l.id)&&<Check size={15}/>}</button>)}</div><div className="lesson-workspace"><article className="lesson-content">
 <div className="tab-panel" key={tab}>{tab===0&&<><Visual type={l.visual}/><div className="explain-blocks">{l.explain.map(([t,b],i)=><section key={t}><span className="explain-index">0{i+1}</span><div><h2>{t}</h2><p>{b}</p></div></section>)}</div><div className="example-box"><Lightbulb size={21}/><div><span className="eyebrow">ПРИМЕР С ЧИСЛАМИ ИЛИ СИТУАЦИЕЙ</span><p>{l.example}</p></div></div>{l.worked&&<div className="lesson-deep-dive"><span className="eyebrow">РАЗБОР ШАГ ЗА ШАГОМ · УЧЕБНЫЙ ПРИМЕР</span><p>{l.worked}</p><h3>Частая ошибка</h3><p>{l.mistake}</p></div>}<button className="primary" onClick={()=>setTab(1)}>Теперь попробую сам <ArrowRight size={17}/></button></>}
 {tab===1&&<><div className="task-box"><span className="eyebrow">ТВОЁ ЗАДАНИЕ</span><h2>Преврати идею в действие</h2><p>{l.task}</p></div><Visual type={l.visual}/><label className="note-label">Моё объяснение своими словами<textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Что заметил? Как объяснишь результат? Что пока непонятно?" rows="5"/></label><p className="footnote">Запись сохраняется в этом браузере. Для пошаговых сделок открой тренажёр рынка.</p><div className="button-row"><button className="secondary" onClick={()=>go('/simulator')}>В тренажёр <ArrowUpRight size={16}/></button><button className="primary" onClick={()=>setTab(2)}>Проверить понимание <ArrowRight size={17}/></button></div></>}
 {tab===2&&<LessonQuiz questions={l.quizzes} onComplete={()=>{complete(l.id);if(next)openLesson(next.id);else go('/course');}} completeLabel={next?'Завершить и к следующему уроку':'Завершить маршрут'}/>}</div>
 </article><aside className="lesson-aside"><div className="aside-card"><span className="eyebrow">ПОСЛЕ ЭТОГО УРОКА</span><h3>Сможешь объяснить</h3><p>{l.subtitle}</p><div className="aside-divider"/><span className="eyebrow">ОТКУДА ИДЕЯ</span>{l.sources.map(([id,q])=>{const b=catalog.find(b=>b.id===id),ref=sourceMap[id]?.[q];return <button key={id+q} className="source-link" onClick={()=>go('/library/'+id+'?q='+encodeURIComponent(q)+(ref?'&page='+ref.page:''))}><BookOpen size={16}/><div><b>{b?.author||id}</b><small>{b?.kind==='summary'?'Пересказ Bookey':ref?'PDF-страница '+ref.page:'Поиск в источнике'}</small></div><ArrowUpRight size={14}/></button>;})}<p className="footnote">Объяснения и задачи адаптированы для курса. Точные страницы и оригиналы — в библиотеке.</p></div><div className="aside-tip"><Target size={20}/><h3>Один урок — один навык</h3><p>Сначала объясни идею без термина. Затем проверь её на примере.</p></div></aside></div></div>;
}

function Simulator({saveEntry,track}){
 const START=SIM_START;
 const [session,setSession]=useStored('campus.simulator',initialSimulator());
 const {seed,visible,trade,events,distance,rr,riskPct,speed,reason}=session;
 const field=key=>value=>setSession(s=>({...s,[key]:typeof value==='function'?value(s[key]):value}));
 const setDistance=field('distance'),setRr=field('rr'),setRiskPct=field('riskPct'),setSpeed=field('speed'),setReason=field('reason'),setEvents=field('events');
 const [playing,setPlaying]=useState(false);
 const candles=useMemo(()=>makeCandles(seed),[seed]);const ended=visible>=candles.length;
 const chronological=[...events].reverse();const st=tradeStats(chronological.map(e=>e.r));
 const balance=simulatorBalance(session),risk=simulatorRisk(session);
 function transact(action){let closed=false;setSession(s=>{const next=action(s);closed=next.events.length>s.events.length;return next;});if(closed){setPlaying(false);track();}}
 function advance(){transact(s=>advanceSimulator(s,uid()));if(ended)setPlaying(false);}
 useEffect(()=>{if(!playing)return;const t=setInterval(advance,950/speed);return()=>clearInterval(t);},[playing,visible,trade,distance,rr,speed]);
 function open(direction){transact(s=>openSimulator(s,direction));}
 function reset(seed){setSession(s=>restartSimulator(s,Number.isInteger(seed)?seed:s.seed));setPlaying(false);}
 function close(){transact(s=>closeSimulator(s,uid()));}
 useEffect(()=>{const fn=e=>{if(e.target.closest('input,textarea,select')||e.metaKey||e.ctrlKey)return;const k=e.key.toLowerCase();if(k==='arrowright'||k==='n'){e.preventDefault();advance();}else if(k==='b'||k==='и')open('long');else if(k==='s'||k==='ы')open('short');else if(k==='c'||k==='с')close();else if(k===' '){e.preventDefault();if(!ended)setPlaying(p=>!p);}};window.addEventListener('keydown',fn);return()=>window.removeEventListener('keydown',fn);});
 const live=trade?tradeResultR(trade,candles[visible-1].c):0;
 const W=300,H=70,ys=st.curve,mn=Math.min(0,...ys),mx=Math.max(1,...ys),yv=v=>6+(mx-v)/(mx-mn)*(H-12),spark=ys.map((v,i)=>(i?'L':'M')+(ys.length>1?i/(ys.length-1)*W:0).toFixed(1)+' '+yv(v).toFixed(1)).join(' ');
 const presets=[17,34,91];
 return <div className="page"><PageHead label="УЧИМСЯ НА ИСКУССТВЕННОМ РЫНКЕ" title="Сначала решение. Потом следующая свеча." text="Здесь тренируется процесс: наблюдать, сформулировать план и выдержать неизвестный исход."/>
 <div className="account-strip stagger">
  <div style={{'--i':0}}><small>Учебный счёт</small><b className={balance>=START?'positive':'negative'}>{money(balance,0)} $</b></div>
  <div style={{'--i':1}}><small>Сделок</small><b>{st.n}</b></div>
  <div style={{'--i':2}}><small>Доля выигрышей</small><b>{st.n?money(st.winRate*100,0)+'%':'—'}</b></div>
  <div style={{'--i':3}}><small>Средний результат</small><b className={st.avg>=0?'positive':'negative'}>{st.n?(st.avg>0?'+':'')+money(st.avg)+'R':'—'}</b></div>
  <div style={{'--i':4}}><small>Макс. просадка</small><b>{st.n?money(st.maxDD)+'R':'—'}</b></div>
  <div className="spark-cell" style={{'--i':5}}><small>Кривая капитала, R</small><svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" className="spark" aria-hidden="true"><line x1="0" x2={W} y1={yv(0)} y2={yv(0)} className="spark-zero"/>{st.n>0&&<path d={spark} className={st.total>=0?'spark-up':'spark-down'}/>}</svg></div>
 </div>
 <div className="simulator-layout"><section><div className="panel simulator-chart"><div className="sim-toolbar"><div><span className="tiny-dot live"/><b>УЧЕБНЫЙ ИНСТРУМЕНТ</b><span className="pill">M15 · синтетика</span></div><strong key={visible} className="price-tick">{money(candles[visible-1].c)}</strong></div><Chart {...{candles,visible,trade}}/>
 {trade&&<div className={'live-pnl '+(live>=0?'positive':'negative')}>Открыта {trade.direction==='long'?'покупка':'продажа'} · сейчас {live>0?'+':''}{money(live)}R ({live>0?'+':''}{money(live*trade.riskMoney,0)} $)</div>}
 <div className="replay-controls"><div><button className="icon-button" aria-label="Повторить график" title="Повторить график, сохранив счёт и историю" disabled={!!trade} onClick={reset}><RotateCcw size={18}/></button><button className="icon-button" aria-label="Случайный рынок" title="Случайный рынок" disabled={!!trade} onClick={()=>reset(Math.floor(Math.random()*100000))}><Shuffle size={18}/></button><span>Свеча {visible} из {candles.length}</span></div><div><button className="secondary speed" onClick={()=>setSpeed(s=>s===1?2:s===2?4:1)} title="Скорость автопоказа">{speed}×</button><button className="secondary" aria-label={playing?'Приостановить автопоказ':'Начать автопоказ'} disabled={ended} onClick={()=>setPlaying(!playing)}>{playing?<Pause size={16}/>:<Play size={16}/>} <span className="hide-xs">{playing?'Пауза':'Автопоказ'}</span></button><button className="primary" disabled={ended} onClick={advance}>Следующая свеча <ChevronRight size={16}/></button></div></div>
 {ended&&<div className="ended-note">Сценарий закончился. История и счёт сохранены. Нажми <Shuffle size={14}/> для нового рынка или <RotateCcw size={14}/>, чтобы пройти этот ещё раз.</div>}</div>
 <div className="simulation-notes"><span><Lightbulb size={18}/></span><p>Будущие свечи скрыты. При касании стопа и цели внутри одной свечи модель выбирает стоп. Расходы зарезервированы внутри лимита риска: 10% от риска движения до стопа. Результат и цель в R показываются после этих расходов; 1R равен выбранному лимиту. Разрыв против стопа может увеличить потерю. Счёт, позиция и история сохраняются автоматически. <span className="hide-touch">Клавиши: <kbd>→</kbd> свеча, <kbd>B</kbd> покупка, <kbd>S</kbd> продажа, <kbd>C</kbd> закрыть, <kbd>Пробел</kbd> автопоказ.</span></p></div>
 <div className="section-title"><h2>Разбор решений</h2><small>{events.length} завершено</small></div>
 {events.length?events.map((e,i)=><div key={e.id} className="trade-event"><span className={e.r>=0?'positive':'negative'}>{e.r>0?'+':''}{money(e.r)}R<small>{e.pnl>0?'+':''}{money(e.pnl,0)} $</small></span><div><b>{e.reason} · {e.direction==='long'?'покупка':'продажа'}</b><p>Вход {money(e.entry)} → выход {money(e.exit)}{e.ambiguous?' · обе границы внутри свечи':''}</p>{e.reasonText&&<small>{e.reasonText}</small>}</div><button className="text-button" disabled={e.saved} onClick={()=>{saveEntry({type:'Тренажёр',title:e.reason,note:e.reasonText||'Причина не была записана',result:money(e.r)+'R',process:'Для разбора',emotion:'Не отмечено',...(simulatorJournalTrade(e)?{trade:simulatorJournalTrade(e)}:{})});setEvents(a=>a.map((x,j)=>j===i?{...x,saved:true}:x));}}>{e.saved?'Сохранено':'В журнал'}{!e.saved&&<ArrowUpRight size={15}/>}</button></div>):<div className="empty-state small-empty"><NotebookPen size={23}/><p>Запиши причину, открой учебную позицию<br/>и раскрывай график по одной свече.</p></div>}</section>
 <aside className="panel order-panel"><span className="eyebrow">ТВОЁ РЕШЕНИЕ</span><h2>План до входа</h2>
 <label>Учебный сценарий<select value={presets.includes(seed)?seed:'random'} disabled={!!trade} onChange={e=>{if(e.target.value!=='random')reset(+e.target.value);}}><option value="17">Последовательность 01</option><option value="34">Последовательность 02</option><option value="91">Последовательность 03</option>{!presets.includes(seed)&&<option value="random">Случайный рынок #{seed}</option>}</select></label>
 <label>Расстояние до стопа <b>{distance}</b><input type="range" min=".5" max="5" step=".5" disabled={!!trade} value={distance} onChange={e=>setDistance(+e.target.value)}/></label>
 <label>Чистая цель после расходов <b>{rr}R</b><input type="range" min="1" max="4" step=".5" disabled={!!trade} value={rr} onChange={e=>setRr(+e.target.value)}/></label>
 <label>Лимит потери с расходами <b>{money(riskPct)}% · {money(risk.budget,2)} $</b><input type="range" min=".25" max="3" step=".25" disabled={!!trade} value={riskPct} onChange={e=>setRiskPct(+e.target.value)}/></label>
 <div className="risk-preview"><div>Движение до стопа <b>{money(trade?.riskIncludesCosts?trade.riskMoney/1.1:risk.priceRisk)} $</b></div><div>Резерв расходов <b>{money(trade?.riskIncludesCosts?trade.riskMoney/11:risk.costs)} $</b></div><div>Плановая потеря всего <b>{money(trade?.riskMoney||risk.budget)} $</b></div><div>Чистая прибыль у цели <b>+{money(risk.targetNet)} $</b></div></div><label>Почему это решение?<textarea rows="4" placeholder="Сценарий, что наблюдаю, когда идея отменяется…" value={reason} disabled={!!trade} onChange={e=>setReason(e.target.value)}/></label>
 {trade?<><div className="open-position"><span className="tiny-dot live"/> Позиция открыта · {trade.direction==='long'?'покупка':'продажа'}<small>Вход {money(trade.entry)} · стоп {money(trade.stop)} · цель {money(trade.target)}</small><small>Риск {money(trade.riskMoney,0)} $ · цель +{money(trade.riskMoney*rr,0)} $</small></div><button className="secondary full" onClick={close}>Закрыть по видимой цене</button></>:<div className="direction-buttons"><button className="buy" disabled={ended||balance<=0||!reason.trim()} onClick={()=>open('long')}>Покупка <ArrowUpRight size={17}/></button><button className="sell" disabled={ended||balance<=0||!reason.trim()} onClick={()=>open('short')}>Продажа <ArrowDownToLine size={17}/></button></div>}
 <p className="footnote">{!trade&&!reason.trim()?'Чтобы открыть позицию, сначала запиши причину. ':''}Можно просто пропустить свечу. Тренажёр оценивает действия на искусственных данных; результат не проверяет рыночную стратегию.</p></aside></div>
 <details className="tool-details"><summary><SlidersHorizontal size={18}/> Открыть калькуляторы риска и ожидания</summary><RiskCalculator/><ExpectancyLab/><DrawdownLab/></details></div>;
}

const situations=[
 {title:'Два стопа подряд',body:'Ты соблюдал правила, но две учебные сделки закрылись с убытком. Возникает мысль: «Сейчас удвою размер и быстро верну».',options:['Удвоить количество при следующем сигнале','Проверить лимит сессии, отметить импульс и продолжать только по исходным правилам','Убрать стоп, чтобы не выбивало'],answer:1,why:'Прошлый убыток не создаёт преимущества. Сначала проверь заранее заданный предел, состояние и правила. При достижении предела занятие завершается.'},
 {title:'Цена ушла без тебя',body:'Ты пропустил вход. Цена быстро выросла, и кажется, что возможность уходит навсегда.',options:['Войти по любой цене','Оценить текущий вход как новую ситуацию по плану','Компенсировать упущенное большим размером'],answer:1,why:'Упущенное движение не уменьшило твой счёт. Новый вход оценивается по текущим условиям, а не по желанию догнать прошлое.'},
 {title:'Нарушил и заработал',body:'Ты вошёл без сигнала и получил +2R. Возникает желание добавить такое действие в метод.',options:['Считать это доказанным преимуществом','Увеличить риск, пока везёт','Отметить нарушение отдельно от прибыли и исследовать гипотезу на последовательных данных'],answer:2,why:'Один удачный исход не подтверждает правило. Положительная награда способна закрепить нарушение, если не разделить процесс и деньги.'},
 {title:'Хочу выйти ровно в ноль',body:'План отменён, но ты держишь позицию: «Продам, когда вернётся к моей покупке».',options:['Ждать любой ценой','Проверить исходное условие отмены; цена покупки не обязывает рынок вернуться','Добавить ещё, чтобы средняя стала удобнее'],answer:1,why:'Это возможное влияние якоря. Следующее действие определяется предварительным планом и фактическим риском, а не психологической привлекательностью нуля.'}
];
function Psychology({openLesson,saveEntry}){
 const [index,setIndex]=useState(0),[choice,setChoice]=useState(null),[shown,setShown]=useState(false),[note,setNote]=useState(''),[saved,setSaved]=useState(false);const s=situations[index];
 return <div className="page"><PageHead label="ПСИХОЛОГИЯ В ДЕЙСТВИИ" title="Замечать реакцию. Выбирать действие." text="Разбираем реальные для обучения ситуации: страх, отыгрыш, спешку и оценку результата."/><div className="psychology-grid"><section className="panel scenario" key={index}><div className="section-title"><span className="eyebrow">СИТУАЦИЯ {index+1} / {situations.length}</span><Brain size={23}/></div><h2>{s.title}</h2><p className="scenario-body">{s.body}</p><h3>Какое действие соответствует устойчивому процессу?</h3><div className="quiz-options">{s.options.map((t,i)=><button key={i} className={(choice===i?'chosen ':'')+(shown&&i===s.answer?'correct ':'')+(shown&&choice===i&&i!==s.answer?'wrong':'')} onClick={()=>{setChoice(i);setShown(false);setSaved(false);}}><span>{i+1}</span>{t}{shown&&i===s.answer&&<Check size={18}/>}</button>)}</div><button className="primary" disabled={choice===null} onClick={()=>setShown(true)}>Разобрать решение <ArrowRight size={17}/></button>{shown&&<div className={'quiz-feedback pop '+(choice===s.answer?'success':'retry')}><b>{choice===s.answer?'Полезное действие.':'Разберём импульс.'}</b><p>{s.why}</p><label>Мой ранний сигнал и действие<textarea rows="3" value={note} onChange={e=>setNote(e.target.value)} placeholder="Например: замечаю быстрые клики → убираю руку с мыши → проверяю лимит…"/></label><div className="button-row"><button className="secondary" disabled={saved||!note.trim()} onClick={()=>{saveEntry({type:'Психология',title:s.title,note,result:'Разбор ситуации',process:choice===s.answer?'Правило выбрано':'Нужно повторить',emotion:'Самонаблюдение'});setSaved(true);}}>{saved?'Сохранено':'Сохранить в журнал'}</button><button className="text-button" onClick={()=>{setIndex((index+1)%situations.length);setChoice(null);setShown(false);setNote('');setSaved(false);}}>Следующая ситуация <ArrowRight size={16}/></button></div></div>}</section><aside><div className="aside-card"><span className="eyebrow">СНАЧАЛА ЗАМЕТЬ ЦЕПОЧКУ</span><div className="psych-chain">{['Событие','Моя интерпретация','Ощущение и импульс','Выбранное действие'].map((t,i)=><div key={i}><span>0{i+1}</span>{t}</div>)}</div><p>Работаем с наблюдаемыми признаками и выполнимыми действиями.</p></div><div className="related-lessons"><h3>Разобраться глубже</h3>{modules.find(m=>m.id==='psychology').lessons.map(l=><button key={l.id} onClick={()=>openLesson(l.id)}>{l.title}<ArrowUpRight size={15}/></button>)}</div></aside></div></div>;
}

function LibraryView({catalog,bookId,report,sourceMap,query}){
 const params=new URLSearchParams(query),[filter,setFilter]=useState('Все'),[q,setQ]=useState(''),[searchLanguage,setSearchLanguage]=useState('ru'),[hits,setHits]=useState(null),[busy,setBusy]=useState(false),[failure,setFailure]=useState('');
 const [tables,setTables]=useState([]),[toc,setToc]=useState([]),[imageLimit,setImageLimit]=useState(80);
 const [pages,setPages]=useState([]),[images,setImages]=useState([]),[tab,setTab]=useState(params.has('page')?1:0),[page,setPage]=useState(Number(params.get('page')||1)),[pageQ,setPageQ]=useState(params.get('q')||'');
 const book=catalog.find(b=>b.id===bookId),guide=guides[bookId];
 useEffect(()=>{setTab(params.has('page')?1:0);setPage(Number(params.get('page')||1));setPageQ(params.get('q')||'');},[bookId,query]);
 useEffect(()=>{setPages([]);setImages([]);setTables([]);setToc([]);setImageLimit(80);setFailure('');let current=true;if(!bookId)return;Promise.all([fetch(publicAsset(`/library/${bookId}/pages.json`)).then(r=>r.json()),fetch(publicAsset(`/library/${bookId}/images.json`)).then(r=>r.json()),fetch(publicAsset(`/library/${bookId}/tables.json`)).then(r=>r.json()),fetch(publicAsset(`/library/${bookId}/toc.json`)).then(r=>r.json())]).then(([p,i,t,o])=>{if(current){setPages(p);setImages(i);setTables(t);setToc(o);}}).catch(()=>current&&setFailure('Не удалось загрузить страницы книги. Проверь соединение и обнови страницу.'));return()=>{current=false;};},[bookId]);
 async function searchAll(){
  if(!q.trim())return;setBusy(true);setFailure('');
  try{
   if(searchLanguage==='ru'){
    const all=await Promise.all(catalog.map(async book=>({book,text:await fetch(publicAsset(`/reading/${book.id}.md`)).then(r=>{if(!r.ok)throw Error();return r.text();})})));
    setHits(all.flatMap(({book,text})=>splitBook(text).chapters.filter(c=>(c.title+' '+c.body).toLowerCase().includes(q.toLowerCase())).map(c=>{const at=c.body.toLowerCase().indexOf(q.toLowerCase());return {book,section:c.index,sectionTitle:c.title,snippet:c.body.slice(Math.max(0,at-65),Math.max(0,at-65)+230).replace(/[*#_]/g,'')};})));
   }else{
    const all=await Promise.all(catalog.map(async book=>({book,pages:await fetch(publicAsset(`/library/${book.id}/pages.json`)).then(r=>r.json())})));
    setHits(all.flatMap(({book,pages})=>pages.filter(p=>p.text.toLowerCase().includes(q.toLowerCase())).map(p=>({book,page:p.page,snippet:p.text.slice(Math.max(0,p.text.toLowerCase().indexOf(q.toLowerCase())-65),p.text.toLowerCase().indexOf(q.toLowerCase())+210)}))));
   }
  }catch{setFailure('Поиск не завершён. Проверь локальные данные.');}finally{setBusy(false);}
 }

 if(book){const current=pages[page-1],found=pageQ?pages.filter(p=>p.text.toLowerCase().includes(pageQ.toLowerCase())):[];return <div className="page library-reader"><button className="back-link" onClick={()=>go('/library')}><ArrowLeft size={16}/> Вся библиотека</button><div className="book-detail-header"><div className="book-cover large-cover"><span>{book.author}</span><strong>{book.title}</strong><i>{book.kind==='summary'?'ОБЗОР BOOKEY':'ЛИЧНАЯ БИБЛИОТЕКА'}</i></div><div><span className={'pill '+(book.kind==='summary'?'amber':'')}>{book.sourceLabel}</span><h1>{book.title}</h1><p>{book.author} · {book.pages} PDF-страниц</p><p className="book-intro">{guide?.intro}</p><a className="secondary inline-button" href={publicAsset('/originals/'+encodeURIComponent(book.filename)+'#page='+page)} target="_blank" rel="noreferrer">Открыть исходный PDF <ExternalLink size={15}/></a></div></div><div className="lesson-tabs">{['Понятно по-русски','Страницы оригинала','Схемы и рисунки','Таблицы и оглавление'].map((t,i)=><button className={tab===i?'active':''} key={i} onClick={()=>setTab(i)}>{t}</button>)}</div>
 {tab===0&&<RussianBookReader key={book.id} book={book} requestedChapter={params.has('chapter')?Number(params.get('chapter')):undefined} onChapter={n=>go('/library/'+book.id+'?chapter='+n)} onSource={n=>{setPage(n);setPageQ('');setTab(1);}}/>}
 {tab===1&&<div className="reader-layout"><section><div className="reader-toolbar"><button aria-label="Предыдущая страница" className="icon-button" disabled={page<=1} onClick={()=>setPage(p=>p-1)}><ChevronLeft size={18}/></button><label>PDF-страница <input aria-label="Номер PDF-страницы" type="number" min="1" max={book.pages} value={page} onChange={e=>setPage(Math.min(book.pages,Math.max(1,Number(e.target.value)||1)))}/><span> / {book.pages}</span></label><button aria-label="Следующая страница" className="icon-button" disabled={page>=book.pages} onClick={()=>setPage(p=>p+1)}><ChevronRight size={18}/></button><a href={publicAsset('/originals/'+encodeURIComponent(book.filename)+'#page='+page)} target="_blank" rel="noreferrer"><ExternalLink size={17}/></a></div>{failure?<p className="error-note">{failure}</p>:!current?<div className="loading-state">Загружаем страницы…</div>:<><div className="source-language"><span className="pill">{current.method==='ocr'?'Автоматическое распознавание':'Извлечённый текст'}</span><span>Оригинал на английском</span></div>{current.render&&<img className="page-render" loading="lazy" src={publicAsset(`/library/${book.id}/${current.render}`)} alt={`Изображение PDF-страницы ${page}`}/>}<details open={!current.render} className="raw-text"><summary>Текст страницы {page}</summary><pre>{current.text||'На странице не извлечён текст. Сверь изображение или исходный PDF.'}</pre></details>{current.flags?.length>0&&<p className="quality-warning">Эта страница отмечена для визуальной проверки: мало текста или сниженная уверенность OCR.</p>}{!current.render&&current.images?.map(src=><img key={src} className="page-figure" loading="lazy" src={publicAsset(`/library/${book.id}/${src}`)} alt={`Иллюстрация из PDF-страницы ${page}`}/>)}</>}</section><aside className="panel reader-search"><h3>Найти в этой книге</h3><label>Английское слово из оригинала<input placeholder="Например: trend, tilt, risk" value={pageQ} onChange={e=>setPageQ(e.target.value)}/></label><small>{pageQ?found.length+' страниц с совпадением':'Поиск по извлечённому тексту'}</small><div className="page-hits">{found.slice(0,80).map(p=><button key={p.page} className={p.page===page?'selected':''} onClick={()=>setPage(p.page)}><b>PDF {p.page}</b><p>{p.text.slice(Math.max(0,p.text.toLowerCase().indexOf(pageQ.toLowerCase())-25),p.text.toLowerCase().indexOf(pageQ.toLowerCase())+105)}</p></button>)}</div><p className="footnote">Номера относятся к PDF, включая обложку. Они могут отличаться от печатных. Искажённое OCR слово может не находиться.</p></aside></div>}
 {tab===2&&<><p className="muted">Извлечённые растровые изображения. Векторные графики и их подписи сохраняются в исходном PDF и на изображениях распознанных страниц.</p><div className="figure-grid">{images.slice(0,imageLimit).map(img=><button className="figure-card" key={img.file} onClick={()=>{setPage(img.pages[0]);setTab(1);}}><img src={publicAsset(`/library/${book.id}/${img.file}`)} loading="lazy" alt={'Рисунок, PDF-страница '+img.pages[0]}/><small>PDF {img.pages.slice(0,4).join(', ')} <ArrowUpRight size={13}/></small></button>)}</div>{images.length>imageLimit&&<button className="secondary" onClick={()=>setImageLimit(n=>n+80)}>Показать ещё · осталось {images.length-imageLimit}</button>}{!images.length&&<div className="empty-state"><FileText/><p>Отдельных растровых изображений не найдено.<br/>Открой оригинальный PDF для векторных схем.</p></div>}</>}
 {tab===3&&<div className="source-structure"><section className="panel"><h2>Оглавление исходного файла</h2><p>Названия сохранены на языке оригинала. Номер ведёт на соответствующую PDF-страницу.</p>{toc.length?toc.map(([level,title,p],i)=><button className="toc-row" key={i} style={{paddingLeft:Math.min(level-1,3)*14}} onClick={()=>{setPage(Math.max(1,p));setTab(1);}}><span>{title}</span><small>PDF {p}</small><ArrowUpRight size={14}/></button>):<p>В этом PDF нет встроенных закладок. Печатное оглавление сохранено среди страниц; темы разобраны на русской вкладке.</p>}</section><section className="panel"><h2>Извлечённые таблицы</h2><p>Автоматическое выделение может нарушать объединённые ячейки и переносы. Для сканов сохраняются изображение и строки OCR, а не восстановленная вручную таблица.</p>{tables.length?tables.map((t,i)=><div className="extracted-table" key={i}><button className="text-button" onClick={()=>{setPage(t.page);setTab(1);}}>Сверить с PDF-страницей {t.page}<ArrowUpRight size={14}/></button><div className="table-scroll"><table><tbody>{t.rows.map((r,j)=><tr key={j}>{r.map((cell,k)=><td key={k}>{cell||'—'}</td>)}</tr>)}</tbody></table></div></div>):<p>Отдельных таблиц автоматический алгоритм не выделил. Это не означает, что таблиц нет в оригинале.</p>}</section></div>}
 </div>;}
 const filtered=catalog.filter(b=>filter==='Все'||filter==='Книги'&&b.kind!=='summary'||filter==='Пересказы'&&b.kind==='summary'||filter==='OCR'&&b.kind==='scan');
 return <div className="page"><PageHead label="ТВОИ ИСТОЧНИКИ, СВЯЗАННЫЕ С УРОКАМИ" title="Библиотека с понятными разборами" text="Все предоставленные материалы: русские объяснения тем, извлечённые страницы и исходные PDF."/><div className="library-summary"><span><b>{catalog.length}</b> источников</span><span><b>{report?.pages?.toLocaleString('ru-RU')||'…'}</b> PDF-страниц</span><span><b>{report?.ocr_pages||'…'}</b> страниц с OCR</span><span><b>{report?.summary_files||6}</b> пересказов Bookey</span></div><form className="library-search" onSubmit={e=>{e.preventDefault();searchAll();}}><Search size={19}/><input aria-label="Поиск во всех книгах" value={q} onChange={e=>{setQ(e.target.value);if(!e.target.value)setHits(null);}} placeholder={searchLanguage==='ru'?'Найти во всех русских разборах: например, риск, тильт или средняя…':'Найти в английских оригиналах: например, risk, tilt или learning…'}/><button className="primary" disabled={busy||!q.trim()}>{busy?'Ищем…':'Найти'}</button></form><div className="reading-search-scope"><span>Искать в:</span><button className={searchLanguage==='ru'?'active':''} onClick={()=>{setSearchLanguage('ru');setHits(null);}}>Русских разборах</button><button className={searchLanguage==='en'?'active':''} onClick={()=>{setSearchLanguage('en');setHits(null);}}>Английских оригиналах</button></div>{failure&&<p className="error-note">{failure}</p>}{hits!==null&&<div className="library-hits"><div className="section-title"><h3>{searchLanguage==='ru'?'Найдено разделов':'Найдено страниц'}: {hits.length}</h3><button className="text-button" onClick={()=>setHits(null)}>Закрыть результаты <X size={15}/></button></div>{hits.slice(0,60).map((h,i)=><button key={i} onClick={()=>go(h.section!==undefined?`/library/${h.book.id}?chapter=${h.section}`:`/library/${h.book.id}?page=${h.page}&q=${encodeURIComponent(q)}`)}><b>{h.book.title} · {h.section!==undefined?h.sectionTitle:"PDF "+h.page}</b><p>{h.snippet}</p></button>)}{!hits.length&&<p>Совпадений нет. Попробуй более короткое слово или переключи язык источника.</p>}{hits.length>60&&<p>Показаны первые 60. Уточни запрос или открой поиск внутри книги.</p>}</div>}<div className="filter-tabs">{['Все','Книги','Пересказы','OCR'].map(t=><button key={t} className={t===filter?'active':''} onClick={()=>setFilter(t)}>{t}</button>)}</div><div className="library-grid">{filtered.map((b,i)=><button className="library-card" key={b.id} onClick={()=>go('/library/'+b.id)}><div className={'book-cover cover-'+i%4}><span>{b.author}</span><strong>{b.title}</strong><div className="cover-lines"/><i>{b.kind==='summary'?'ОБЗОР BOOKEY':b.kind==='scan'?'КНИГА / СКАН':'КНИГА / PDF'}</i></div><div className="library-card-info"><span className={'source-type '+(b.kind==='summary'?'amber-text':'')}>{b.sourceLabel}</span><h3>{b.title}</h3><p>{b.author}</p><div><small>{b.pages} страниц · {b.category}</small><ArrowUpRight size={16}/></div></div></button>)}</div><details className="tool-details"><summary><FileText size={18}/> Как проверены извлечённые данные</summary><p>Для каждого PDF сохранены постраничный текст, исходные координатные блоки, растровые изображения, доступные ссылки и оглавление, обнаруженные таблицы и SHA-256 оригинала. Сканы обработаны локальным OCR. Количество обработанных страниц сверено с PDF.</p><p>Автоматическая проверка не гарантирует безошибочность текста. Формулы, мелкие подписи и таблицы требуют сверки с исходной страницей. Страницы с малым количеством текста и сниженной уверенностью перечислены в отчёте.</p><a href={publicAsset("/data/quality-report.json")} target="_blank" rel="noreferrer">Открыть количественный отчёт <ExternalLink size={14}/></a></details></div>;
}

function Glossary({query}){const [q,setQ]=useState(query);useEffect(()=>setQ(query),[query]);const items=glossary.filter(g=>(g.term+' '+g.ru+' '+g.body).toLowerCase().includes(q.toLowerCase()));return <div className="page"><PageHead label="БЕЗ ЯЗЫКОВОГО БАРЬЕРА" title="Английский термин → понятный смысл" text="Не заучивай ярлык. Сначала пойми, какое действие или наблюдение за ним стоит."/><div className="input-with-icon"><Search size={19}/><input aria-label="Поиск термина" value={q} onChange={e=>setQ(e.target.value)} placeholder="Например: stop, просадка, ликвидность…"/><small>{items.length} терминов</small></div><div className="glossary-grid">{items.map(g=><article className="panel glossary-card" key={g.term}><span className="eyebrow">{g.term}</span><h2>{g.ru}</h2><p>{g.body}</p></article>)}</div>{!items.length&&<div className="empty-state"><Search/><p>Термин не найден. Попробуй его русское или английское название.</p></div>}</div>;}

function Knowledge({items,selected}){const [q,setQ]=useState('');const current=items.find(x=>x.id===selected);const filtered=items.filter(x=>(x.title+' '+x.body).toLowerCase().includes(q.toLowerCase()));return <div className="page"><PageHead label="ТВОЙ ОБНОВЛЁННЫЙ УЧЕБНИК" title="База знаний" text="Сохранённые главы, справочники и шаблоны из первоначального учебника, дополненные психологией."/>{current?<><button className="back-link" onClick={()=>go('/knowledge')}><ArrowLeft size={16}/> Все главы</button><article className="panel markdown-body"><ReactMarkdown remarkPlugins={[remarkGfm]} urlTransform={url=>url.startsWith('knowledge:')?url:defaultUrlTransform(url)} components={{a:({href,children})=>href?.startsWith('knowledge:')?<button className="inline-link" onClick={()=>go('/knowledge/'+href.slice(10))}>{children}</button>:<a href={href} target="_blank" rel="noreferrer">{children}</a>}}>{current.body}</ReactMarkdown></article></>:<><div className="input-with-icon"><Search size={18}/><input aria-label="Поиск в базе знаний" value={q} onChange={e=>setQ(e.target.value)} placeholder="Найти главу или понятие…"/><small>{filtered.length} глав</small></div><div className="knowledge-list">{filtered.map(item=><button key={item.id} className="knowledge-row" onClick={()=>go('/knowledge/'+item.id)}><FileText size={19}/><div><b>{item.title}</b><small>{item.section}</small></div><ArrowUpRight size={17}/></button>)}</div>{!filtered.length&&<div className="empty-state"><Search/><p>Совпадений нет.</p></div>}</>}</div>;}

function PageHead({label,title,text}){return <div className="page-head"><div className="eyebrow">{label}</div><h1>{title}</h1><p>{text}</p></div>;}
